{% assign steps = site.data.affiliations | sort: "date" | reverse %}

<div class="horizontal-timeline">
    {% for step in steps %}
    <div class="horizontal-timeline-entry">
        <!-- Including the horizontal-timeline-card here -->
        {% include horizontal_timeline_card.html %}
    </div>
    {% endfor %}

</div>","numCharactersInRequestedRange":357,"totalLinesInFile":12}

{"contents":".timeline {
	img {
		max-width: 100%
	}

	.item {
		padding-top: 100px;
		min-height: 150px;
		position: relative
	}

	.item:before,
	.last-item:after {
		background: var(--global-bg-color);
		border: 8px solid var(--global-text-color);
		border-radius: 50%;
		width: 40px;
		height: 40px;
		display: inline-block;
		content: "";
		margin-left: 1rem;
		position: relative;
		z-index: 1;
		left: calc(2% - 36px)
	}

	.vertical-line {
		width: 8px;
		background-color: var(--global-text-color);
		position: absolute;
		left: calc(2% - 5px);
		top: 0;
		bottom: 0
	}

	.item .card-panel {
		margin: 0;
		margin: 2rem 0 0 3rem
	}

	.item-date {
		margin-top: -60px;
		margin-left: 4rem
	}

	.last-item {
		padding-top: 80px;
		height: 70px;
		position: relative;
		margin-left: 0.85rem
	}

	.card-body {
		display: grid;
		grid-auto-flow: column;
		grid-column-gap: 1rem
	}
}


// Horizontal Timeline

/* Horizontal Timeline */
/* Styling for the horizontal timeline card within .horizontal-timeline scope */
.horizontal-timeline {
	display: flex;
	flex-wrap: wrap;
	justify-content: space-between;
}

